function glow(color){return new T.MeshBasicMaterial({color});}
function seed(n){return Math.abs(Math.sin(n*127.1+311.7)*43758.5453)%1;}
function base(bg){const scene=new T.Scene();scene.background=new T.Color(bg);const camera=new T.PerspectiveCamera(38,1,.1,160);scene.add(new T.HemisphereLight(0xffffff,0x647480,2.1));const key=new T.DirectionalLight(0xffeddf,4.5);key.position.set(-8,15,9);scene.add(key);const fill=new T.DirectionalLight(0xa8d9ff,2.7);fill.position.set(10,6,-5);scene.add(fill);return {scene,camera,update:()=>{},resize:()=>{}};}
function env(renderer){const s=new T.Scene();s.background=new T.Color('#a7beca');const wm=new T.MeshBasicMaterial({color:'#ffffff',side:T.DoubleSide});for(const [x,y,z,w,h] of [[0,8,0,14,9],[-8,1,0,4,12],[8,2,-4,4,14]]){const p=mesh(new T.PlaneGeometry(w,h),wm,s,x,y,z);p.lookAt(0,0,0);}const pm=new T.PMREMGenerator(renderer);const target=pm.fromScene(s,.015);pm.dispose();s.traverse(o=>{if(o.geometry)o.geometry.dispose()});wm.dispose();return target.texture;}
