for(let i=0;i<38;i++){const x=(i%10-4.5)*4.6,z=-5-Math.floor(i/10)*5;if(Math.abs(x)<5&&z>-13)continue;const ht=2+seed(i)*10,w=1.4+seed(i+99)*1.6,d=1.8+seed(i+44)*1.6;const b=box(group,w,ht,d,i%3?stone:dark,x,ht/2,z);b.castShadow=true;box(group,w+.15,.16,d+.15,stone,x,ht+.08,z);for(let j=0;j<Math.floor(ht/.7);j++){box(group,w*.8,.13,.03,j%3===0?light:glass,x,.6+j*.7,z+d/2+.025);}if(i%3===0)box(group,.09,ht,.04,orange,x+w*.25,ht/2,z+d/2+.03);}
// Community hall: layered glass, copper ribs and a broad curved roof.
box(group,9,2.7,5,glass,0,1.5,-6);box(group,9.4,.2,5.4,stone,0,.2,-6);box(group,9.4,.16,5.4,stone,0,2.9,-6);
for(let i=0;i<17;i++){box(group,.08,2.8,5.1,stone,-4.4+i*.55,1.5,-6);box(group,.035,2.4,.04,orange,-4.2+i*.52,1.55,-3.44);}
for(let j=0;j<3;j++)box(group,8.5,.06,.05,light,0,.7+j*.8,-3.42);
