const beam=mesh(new T.ConeGeometry(1.5,1.35,24,1,true),new T.MeshBasicMaterial({color:'#bfffff',transparent:true,opacity:.10,side:T.DoubleSide,depthWrite:false,blending:T.AdditiveBlending}),g,0,-.15,0);beam.rotation.z=Math.PI;
const mug=new T.Group();g.add(mug);mesh(new T.CylinderGeometry(.4,.36,.82,40),pink,mug,-2.3,-1.5,.7);const handle=mesh(new T.TorusGeometry(.26,.07,12,32),pink,mug,-1.87,-1.46,.7);for(const x of [-2.43,-2.2]){mesh(new T.SphereGeometry(.075,16,16),pearl,mug,x,-1.35,1.08);mesh(new T.SphereGeometry(.035,12,12),mat('#332343'),mug,x,-1.35,1.14);}
const objects=[];for(let i=0;i<7;i++){const o=mesh(i%2?new T.TorusGeometry(.28,.085,16,32):new T.IcosahedronGeometry(.33,2),[pink,lilac,mat('#81e1c9',.35,.16)][i%3],g);objects.push(o);}
const orbit=mesh(new T.TorusGeometry(4.2,.012,5,120),new T.MeshBasicMaterial({color:'#ffffff',transparent:true,opacity:.5}),g);orbit.rotation.x=1.2;
